insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-issuer-tags-four-high-schools-s689','decision','Four high schools registered with empty issuer tags','S689 conductor: the 06:24Z daily run (31b4465a) brought Foothill, Granada, Kimball and Livermore High School into kb/credentials.json with no entry in kb/reference/issuer_tags.json, so tests/issuer_tags.test.js failed every PR''s test check (11/12). #3589 (41cae8c9, 07:27Z) registered them with empty lists, matching an absent issuer, as d-issuer-tags-registered-empty-s684 did.',array['credentials','issuer-tags','ci'],'proposed','#3589','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('d-reader-pages-ship-after-two-rounds-s689','decision','The reader''s page checks shipped on their verified part after two rounds','S689 conductor: after two second-reader rounds #3587 merged (cd9e8451, 08:19Z) on its verified part: the ligature fold, every not_found of a marked program marked, the stage hold. The open items went to COBIx (#3587 comment 7033925843); he confirmed two and added a fold point, and follow-up #3590 (2d3d28b2, 09:37Z) closed them with 0 flips against main.',array['program-requirements','page-checks','review'],'proposed','#3587; #3590','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('d-ccsf-outline-trial-no-staff-names-s689','decision','City College of San Francisco''s outline trial files outcomes only','S689 conductor: City College of San Francisco''s outline trial waits until the reader files parsed outcomes only (course id, outcome text, report url), never whole report-28 pages, which name curriculum staff. This keeps the trial clear of a staff-data hold and is reversible. Whether other colleges'' committed trial pages that name staff stay goes to a plain session with COBIx.',array['course-outcomes','privacy','ccsf'],'proposed','docs/session_690_handoff.md','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('m-reread-third-ten-s689','milestone','The reread plan''s third ten posted and loaded','S689: Sierra, Barstow, Pasadena City, Rio Hondo, Los Angeles Harbor, College of San Mateo, College of the Sequoias, Fresno City, Contra Costa and Madera reread, the better record kept, posted and loaded: 37 rows replaced, 56 inserted, $8.32 of extraction. Live read 44695498920; files in #3591 (d449bb5d). Los Angeles Harbor 44947 held for a person; Madera 39814 restored.',array['program-requirements','reread','keep-the-better'],'proposed','#3591; run 44695498920','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('m-santa-rosa-junior-reread-s689','milestone','Santa Rosa Junior''s ligature refusals read again and loaded','S689: after #3587''s fold, Santa Rosa Junior''s 34 refusals got a fresh capture and extract (run 44701011374, $4.22): 22 found their own page, 12 did not. Keep-the-better 22 new, 7 kept, 3 restored, 1 held (37014); reread 44703039037 posted 29 (6 replacing); load 44703311509 inserted 23. Census gaps there 41 to 19. 13898, a known wrong page, stayed unpaid.',array['program-requirements','reread','santa-rosa-junior'],'proposed','#3591; run 44703311509','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('m-feather-river-palomar-outlines-s689','milestone','Feather River''s and Palomar''s outlines loaded','S689: after #3586''s reader fixes (9d11684a), Feather River read 44695075698 loaded 336 SLO rows (load 44700832207; report 485 prints no objectives) and Palomar read 44695267546 loaded 1,108 SLO and 1,106 objective rows (load 44708472734): 2,550 rows. Feather River''s older read 44535960153 is never_load. The files ride #3595.',array['course-outcomes','slo','objectives'],'proposed','#3586; #3595','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('m-display-build-live-s689','milestone','Display build 4c57fd250cce live, confirmed by its closing count','S689: display build 4c57fd250cce replaces 3361e3aa5b7d: one college first (Barstow, run 44718082566, 68 of 68), the live gate (migrate 44718607626), the whole build (44718939233: 18,391 written, 68 current, no errors) and the closing count (migrate 44719715170): 18,459 rows at the new build, 15 and 16 at two older builds, none of 18,490 without a display or key. Page file: #3598.',array['program-requirements','display','conductor'],'proposed','#3598; migrate run 44719715170','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('m-census-5069-s689','milestone','The gap census: 5,069 programs left','S689: harvest-gap-census run 44719996895 on main fb454129 (10:36Z): 5,069 programs left of 20,282, 76 fewer than 5,145; passing 15,120 (15,044 before); collected with gaps 93; places_none 396 to 309, page_not_found up 10. Read after the night''s posts and display build 4c57fd250cce.',array['program-requirements','census','harvest-gap'],'proposed','run 44719996895','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('f-ligature-refusals-s689','fact','PDF ligatures made rule A refuse programs'' own pages','S689: Santa Rosa Junior''s PDF prints certificate headings with the fi ligature, so rule A refused 34 programs (31 certificates). The second reader''s replay over 4,705 filed PDF windows at 31 colleges: the fold turns 203 refusals into accepts, none wrong. The 31 are the replay''s scope; on main the ligature text sits at four colleges: Cañada, College of the Desert, Santa Rosa Junior, Solano.',array['program-requirements','page-checks','pdf'],'proposed','#3587; docs/kb-notes/methodology-a-pdf-ligature-hides-a-heading-from-an-exact-match.md','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('p-sources-from-repays-refused-pages-s689','pitfall','A sources_from read re-pays pages the page checks refused','S689: stage_sources handed staged text back to programs the rules had refused: City College of San Francisco''s preview 44596600042 would have extracted 40 refused programs, 28 on course-description pages, and Santa Rosa Junior 13898 got p.435. #3587 and #3590 hold a staged page the rules did not accept; pay for a refused program only through a fresh capture and extract.',array['program-requirements','page-checks','cost'],'proposed','#3587; #3590','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('p-reader-cap-hides-mtsac-results-s689','pitfall','A trial on whole pages passed while the full read, cut at the Reader''s cap, failed','S689: the Reader keeps 400,000 characters of a page''s HTML; Mt. San Antonio''s SLO results block sits past 671,000. The 12-page trial parsed whole filed pages and passed, while full read 44695707506 filed the course listing as every page''s SLOs; it was canceled after 2 of 5 parts and is never_load. read_one now cuts the browser''s whole HTML at that length (#3586).',array['course-outcomes','slo','mt-san-antonio'],'proposed','#3586','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('f-golden-west-474-header-rows-s689','fact','Golden West''s SLO rows carry a header as an outcome','S689 live read (09:33Z): Golden West has 568 SLO and 580 objective rows in course_outcomes; 474 SLO rows carry the Course Outcomes header as an outcome (470 as the first), all from read 41399075269. The fix is a guarded update with before-values in its receipt, and a reader fix for that HTML path; neither has run.',array['course-outcomes','slo','golden-west'],'proposed','second reader on #3586; live read 2026-11-20','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('f-desert-prior-catalog-behind-robots-s689','fact','College of the Desert''s 2025-26 catalog sits behind robots.txt','S689: none of Desert''s 8 not-printed programs is readable in a prior year. The guessed 2025-26 PDF answers 404 (run 44710248023); the catalog page links only 2026-27 and an archive (44710824364), online only (44711286839), and robots.txt disallows catalog.collegeofthedesert.edu/archive/2025-2026/ (44711759115). The 8 keep their gap; a blocked_sources row rides #3592.',array['program-requirements','rule-d','blocked-sources'],'proposed','#3592','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('f-copper-mountain-catalog-moved-s689','fact','Copper Mountain''s catalog moved to cmccd.curriqunet.com','S689: Copper Mountain''s catalog now lives at cmccd.curriqunet.com, and the address in its registry row answers 404. The row changes through a plan with a receipt or through the weekly census apply (Sundays).',array['program-requirements','registry','copper-mountain'],'proposed','S689 pages worker','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20'),
('q-trial-pages-file-staff-names-s689','question','Should committed outline trial pages that name staff stay?','S689: the second reader found that City College of San Francisco''s report 28 names curriculum staff, and that 37 outline trial pages already on main file originator names. Should committed trial pages that name staff stay, be cut to parsed outcomes, or be removed? For a plain session with COBIx; the CCSF trial already waits on outcomes only (d-ccsf-outline-trial-no-staff-names-s689).',array['course-outcomes','privacy','governance'],'proposed','second reader on #3586','SkyTern (S689), the conductor',null,'SkyTern (S689)',date '2026-11-20')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-collection-first-sam-2026-11-20','decision','Collection comes first: data waves before fixes, one follow-up a night','Sam, 2026-11-20 2:24 AM PT, relayed by COBIx on #3584 (comment 7037137301): "get all the cows back in the pasture first and then we can tend to their needs." Data waves come first; a fix goes ahead of the next wave only if it blocks it or would file wrong rows into live tables. Minor findings and hunches go into one follow-up PR per night; review rounds match what the change needs.',array['conductor','collection','review','sam-ruling'],'verified','#3584 comment 7037137301','Sam (relayed by COBIx)',now(),'SkyTern (S689)',date '2026-11-20')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
